'use client'

import { useState } from 'react'
import { Search, UserMinus, UserPlus, ShieldAlert, ShieldCheck } from 'lucide-react'
import { addBonusQuotaAction, toggleUserSuspensionAction } from '@/app/actions/adminActions'

interface User {
  id: string
  email: string
  bonus_quota: number
  is_suspended: boolean
}

export default function UserManagement({ initialUsers }: { initialUsers: User[] }) {
  const [search, setSearch] = useState('')
  const [users, setUsers] = useState(initialUsers)
  const [loading, setLoading] = useState<string | null>(null)

  const filteredUsers = users.filter(u => u.email.toLowerCase().includes(search.toLowerCase()))

  const handleAddQuota = async (userId: string, amount: number) => {
    setLoading(`${userId}-quota`)
    const res = await addBonusQuotaAction(userId, amount)
    if (res.success) {
      alert(`Harika! Kullanıcıya +${amount} adet yeni "Sihirli Taslak" ✨ hakkı başarıyla tanımlandı.`)
      setUsers(users.map(u => u.id === userId ? { ...u, bonus_quota: u.bonus_quota + amount } : u))
    } else {
      alert(res.error)
    }
    setLoading(null)
  }

  const handleToggleSuspension = async (userId: string, currentStatus: boolean) => {
    setLoading(`${userId}-suspend`)
    const res = await toggleUserSuspensionAction(userId, currentStatus)
    if (res.success) {
      const msg = !currentStatus ? 'Kullanıcı hesabı askıya alındı. 🚫' : 'Kullanıcı hesabı yeniden aktif edildi. ✅'
      alert(msg)
      setUsers(users.map(u => u.id === userId ? { ...u, is_suspended: !currentStatus } : u))
    } else {
      alert(res.error)
    }
    setLoading(null)
  }

  return (
    <div className="bg-white rounded-[2.5rem] shadow-sm border border-gray-100 overflow-hidden mt-12 animate-in fade-in slide-in-from-bottom-10 duration-1000">
      <div className="p-8 border-b border-gray-50 flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white">
        <h2 className="text-2xl font-black text-gray-900 flex items-center gap-3">
          <Search className="text-sky-500" />
          Kullanıcı Yönetimi (CRM)
        </h2>
        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input
            type="text"
            placeholder="E-posta ile kullanıcı ara..."
            className="w-full pl-12 pr-4 py-3 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-sky-500/20 focus:border-sky-500 transition-all font-medium text-sm"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-gray-50/50 text-gray-400 text-[10px] font-black uppercase tracking-widest">
              <th className="px-8 py-5">Kullanıcı</th>
              <th className="px-8 py-5">Bonus Kota</th>
              <th className="px-8 py-5">Durum</th>
              <th className="px-8 py-5 text-right">Aksiyonlar</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filteredUsers.length > 0 ? (
              filteredUsers.map((user) => (
                <tr key={user.id} className={`hover:bg-gray-50/30 transition group ${user.is_suspended ? 'bg-red-50/20' : ''}`}>
                  <td className="px-8 py-6">
                    <p className="font-bold text-gray-900">{user.email}</p>
                    <p className="text-[10px] text-gray-400 font-medium">ID: {user.id}</p>
                  </td>
                  <td className="px-8 py-6">
                    <span className="px-3 py-1 bg-emerald-50 text-emerald-600 rounded-lg text-xs font-black border border-emerald-100">
                      +{user.bonus_quota} Sihirli Taslak
                    </span>
                  </td>
                  <td className="px-8 py-6">
                    {user.is_suspended ? (
                      <span className="flex items-center gap-1.5 text-red-500 font-bold text-xs">
                        <ShieldAlert size={14} />
                        Askıda
                      </span>
                    ) : (
                      <span className="flex items-center gap-1.5 text-emerald-500 font-bold text-xs">
                        <ShieldCheck size={14} />
                        Aktif
                      </span>
                    )}
                  </td>
                  <td className="px-8 py-6 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <button
                        onClick={() => handleAddQuota(user.id, 5)}
                        disabled={loading === `${user.id}-quota`}
                        className="px-3 py-1.5 bg-sky-50 text-sky-600 rounded-xl text-[10px] font-black hover:bg-sky-600 hover:text-white transition-all disabled:opacity-50"
                      >
                        +5 Taslak
                      </button>
                      <button
                        onClick={() => handleAddQuota(user.id, 10)}
                        disabled={loading === `${user.id}-quota`}
                        className="px-3 py-1.5 bg-indigo-50 text-indigo-600 rounded-xl text-[10px] font-black hover:bg-indigo-600 hover:text-white transition-all disabled:opacity-50"
                      >
                        +10 Taslak
                      </button>
                      <button
                        onClick={() => handleToggleSuspension(user.id, user.is_suspended)}
                        disabled={loading === `${user.id}-suspend`}
                        className={`p-2 rounded-xl transition-all ${
                          user.is_suspended
                            ? 'bg-emerald-50 text-emerald-600 hover:bg-emerald-600 hover:text-white'
                            : 'bg-red-50 text-red-600 hover:bg-red-600 hover:text-white'
                        } disabled:opacity-50`}
                        title={user.is_suspended ? 'Aktif Et' : 'Askıya Al'}
                      >
                        {user.is_suspended ? <UserPlus size={16} /> : <UserMinus size={16} />}
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={4} className="px-8 py-10 text-center text-gray-400 font-bold italic">
                  Kullanıcı bulunamadı.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}
